(6097305, 898132, 98339, '<td valign="top">how much coffee and milk did you go through for this one???  what I really like about this are the colors...all of them...they make me want to reach for the cup of coffee...great job</td>', 'how much coffee and milk did you go through for this one???  what I really like about this are the colors...all of them...they make me want to reach for the cup of coffee...great job', '2010-07-19 13:37:21.000000', NULL, 1),
(6097306, 898266, 96751, '<td valign="top">Well done!  A tiny bit more dodging on the oreo to make it stand out more, and it would have been perfect.</td>', 'Well done!  A tiny bit more dodging on the oreo to make it stand out more, and it would have been perfect.', '2010-07-19 13:37:49.000000', NULL, 1),
(6097308, 898241, 96751, '<td valign="top">Nice processing.  If there was enough extra space, I might have cropped a bit tighter on the right and less on the left, to add some negative area, and a more balanced rule of thirds composition.</td>', 'Nice processing.  If there was enough extra space, I might have cropped a bit tighter on the right and less on the left, to add some negative area, and a more balanced rule of thirds composition.', '2010-07-19 13:39:03.000000', NULL, 1),
(6097311, 898264, 96751, '<td valign="top">I love this type of shot.  Don''t know that I''d do anything different, but perhaps having one of the fronds in sunlight for added depth?</td>', 'I love this type of shot.  Don''t know that I''d do anything different, but perhaps having one of the fronds in sunlight for added depth?', '2010-07-19 13:40:17.000000', NULL, 1),
(6097313, 898258, 96751, '<td valign="top">Nice abstract macro.  Good lighting and pleasing lines.</td>', 'Nice abstract macro.  Good lighting and pleasing lines.', '2010-07-19 13:40:44.000000', NULL, 1),
(6097316, 897694, 96751, '<td valign="top">VERY groovy!  Hope you''ll share your set up.</td>', 'VERY groovy!  Hope you''ll share your set up.', '2010-07-19 13:41:29.000000', NULL, 1),
(6097318, 897767, 23484, '<td valign="top">Nice detail.</td>', 'Nice detail.', '2010-07-19 13:42:22.000000', NULL, 1),
(6097320, 898236, 96751, '<td valign="top">Well caught!  I like the splashing blobs all around the glass, and the red drip.  I find the line between surface and background too harsh though.</td>', 'Well caught!  I like the splashing blobs all around the glass, and the red drip.  I find the line between surface and background too harsh though.', '2010-07-19 13:42:40.000000', NULL, 1),
(6097321, 898145, 23484, '<td valign="top">Beautiful shot. Nicely composed and great color. The ripples really add a nice effect.</td>', 'Beautiful shot. Nicely composed and great color. The ripples really add a nice effect.', '2010-07-19 13:43:20.000000', NULL, 1),
(6097322, 898174, 96751, '<td valign="top">Gorgeous portrait!  Love the rotated angle and the high key on the left.  Fabulous process.  Doesn''t hurt to be so gorgeous either!!</td>', 'Gorgeous portrait!  Love the rotated angle and the high key on the left.  Fabulous process.  Doesn''t hurt to be so gorgeous either!!', '2010-07-19 13:43:24.000000', NULL, 1),
(6097323, 898152, 23484, '<td valign="top">I like the composition and the symetry.</td>', 'I like the composition and the symetry.', '2010-07-19 13:44:07.000000', NULL, 1),
(6097324, 898095, 23484, '<td valign="top">This is so coo. It has that old turn of the century B&amp;W look.</td>', 'This is so coo. It has that old turn of the century B&W look.', '2010-07-19 13:44:45.000000', NULL, 1),
(6097325, 898088, 23484, '<td valign="top">The angles and the detail are very nice.</td>', 'The angles and the detail are very nice.', '2010-07-19 13:45:14.000000', NULL, 1),
