(6097356, 898174, 114225, '<td valign="top">Good take on the original. I especially like how you cleaned up the background to put more focus on the subject.</td>', 'Good take on the original. I especially like how you cleaned up the background to put more focus on the subject.', '2010-07-19 14:07:11.000000', NULL, 1),
(6097362, 898003, 114225, '<td valign="top">Great re-creation. Wonderful amount of detail in this photo.</td>', 'Great re-creation. Wonderful amount of detail in this photo.', '2010-07-19 14:13:40.000000', NULL, 1),
(6097364, 898114, 114225, '<td valign="top">I like this photo overall. I do prefer the original''s top down view, as it gave the photo a dreamier look to it.</td>', 'I like this photo overall. I do prefer the original''s top down view, as it gave the photo a dreamier look to it.', '2010-07-19 14:14:35.000000', NULL, 1),
(6097369, 898080, 114225, '<td valign="top">Great recreation of the scene. I don''t know that I like the added blurriness/noise in this version.</td>', 'Great recreation of the scene. I don''t know that I like the added blurriness/noise in this version.', '2010-07-19 14:22:51.000000', NULL, 1),
(6097371, 898128, 114225, '<td valign="top">Great re-creation of the original. I really like what you did to the colors of this photo.</td>', 'Great re-creation of the original. I really like what you did to the colors of this photo.', '2010-07-19 14:23:33.000000', NULL, 1),
(6097402, 897859, 114225, '<td valign="top">I like your take on this entry. The dark surface adds a bit of drama.</td>', 'I like your take on this entry. The dark surface adds a bit of drama.', '2010-07-19 15:17:45.000000', NULL, 1),
(6097430, 897767, 113278, '<td valign="top">This is really well lit and well done. The only thing I see different from the original is the look of the dog. I love how the dog is looking up in the original, really adds something and just kinda grabs you. If the dog in this shot had that look it would be a solid 10, but I still give you a 9. Good luck.</td>', 'This is really well lit and well done. The only thing I see different from the original is the look of the dog. I love how the dog is looking up in the original, really adds something and just kinda grabs you. If the dog in this shot had that look it would be a solid 10, but I still give you a 9. Good luck.', '2010-07-19 16:03:02.000000', NULL, 1),
(6097472, 898091, 103142, '<td valign="top">Funny idea, but I like the viewpoint of the original better. You don''t get the worry on his face as well when it''s such a low angle :P</td>', 'Funny idea, but I like the viewpoint of the original better. You don''t get the worry on his face as well when it''s such a low angle :P', '2010-07-19 17:02:02.000000', NULL, 1),
(6097476, 898044, 103142, '<td valign="top">Better than the original, however this seems pretty dark on my screen and the colors seem a little off... Sorry. -5-</td>', 'Better than the original, however this seems pretty dark on my screen and the colors seem a little off... Sorry. -5-', '2010-07-19 17:04:21.000000', NULL, 1),
(6097479, 898254, 103142, '<td valign="top">It''s replicated nicely, but I like the original better. The glass is very dark here, and looks almost more like a piece of candy. I wish the light would have illuminated it more to get more of a glow to make it more intriguing.</td>', 'It''s replicated nicely, but I like the original better. The glass is very dark here, and looks almost more like a piece of candy. I wish the light would have illuminated it more to get more of a glow to make it more intriguing.', '2010-07-19 17:05:52.000000', NULL, 1),
(6097486, 898103, 46918, '<td valign="top">Nice shot....I think the lighting should have been a little different (not under your control) I definately like the subject and the cloud cover.</td>', 'Nice shot....I think the lighting should have been a little different (not under your control) I definately like the subject and the cloud cover.', '2010-07-19 17:12:32.000000', NULL, 1),
(6097490, 898229, 46918, '<td valign="top">Good DOF and I love the detail that is shown. Good shot.</td>', 'Good DOF and I love the detail that is shown. Good shot.', '2010-07-19 17:13:59.000000', NULL, 1);
