(6101937, 898254, 104009, '<td valign="top">great reproduction.  can''t remember who did the original but remember the shot and title.  7 (eta...i went back to look at the original and got a chuckle...you got my honest vote and comment.  it is a great reproduction)</td>', 'great reproduction.  can''t remember who did the original but remember the shot and title.  7 (eta...i went back to look at the original and got a chuckle...you got my honest vote and comment.  it is a great reproduction)', '2010-07-23 11:47:37.000000', NULL, 1),
(6101941, 898261, 98022, '<td valign="top">Nice take on the original. I like the B/W treatment - adds to the graphic impact. Excellent clarity also.</td>', 'Nice take on the original. I like the B/W treatment - adds to the graphic impact. Excellent clarity also.', '2010-07-23 12:13:15.000000', NULL, 1),
(6101945, 898114, 98022, '<td valign="top">Good image with nice lighting on the rose. The dark top left corner is distracting. IMHO, a tighter crop to eliminate that element would have been a benefit. Overall very good though.</td>', 'Good image with nice lighting on the rose. The dark top left corner is distracting. IMHO, a tighter crop to eliminate that element would have been a benefit. Overall very good though.', '2010-07-23 12:18:52.000000', NULL, 1),
(6101949, 898145, 98022, '<td valign="top">Very good improvement on the original. Great lighting and I really like the ripples in the water. 8</td>', 'Very good improvement on the original. Great lighting and I really like the ripples in the water. 8', '2010-07-23 12:22:28.000000', NULL, 1),
(6101951, 897767, 98022, '<td valign="top">Good pet portrait and an improvement over the original. Having the focal point on the eyes instead of the mouth would have made this excellent.</td>', 'Good pet portrait and an improvement over the original. Having the focal point on the eyes instead of the mouth would have made this excellent.', '2010-07-23 12:27:23.000000', NULL, 1),
(6101955, 898132, 98022, '<td valign="top">Great job capturing the drops and splashes!</td>', 'Great job capturing the drops and splashes!', '2010-07-23 12:31:09.000000', NULL, 1),
(6101985, 898080, 61396, '<td valign="top">Took me a while to guess the cow rear end. I like how the high contrast makes the different figures inseparable.</td>', 'Took me a while to guess the cow rear end. I like how the high contrast makes the different figures inseparable.', '2010-07-23 13:33:58.000000', NULL, 1),
