(6107866, 898145, 94235, '<td valign="top">Congrats Irene! A real zen type feel to this one and a beautiful <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=35965" rel="nofollow" target="_blank">Dax</a> reproduction.</td>', 'Congrats Irene! A real zen type feel to this one and a beautiful  Dax reproduction.', '2010-07-28 19:25:12.000000', NULL, 0),
